{
  "changes": [
    {
      "shot": 1,
      "replacement": "【分镜1】\n中景，固定镜头，黄昏的光线从窗外斜射入室内，【姜蘅之】位于画面右侧，处于画面层次的中景，背对窗户，身体朝向画面左侧，视线看向画面左侧的【沈淮青】，姿态从容，展示全身；【沈淮青】位于画面左侧，处于画面层次的中景，身体微微前倾，朝向画面右侧，视线看向画面右侧的【姜蘅之】，神情急切，展示全身。两人之间隔着一段距离，气氛紧张。"
    },
    {
      "shot": 2,
      "replacement": "【分镜2】\n脸部特写，缓慢推进，【姜蘅之】位于画面中央，处于画面层次的前景，面部朝向镜头，视线看向镜头前方（即画面左侧的【沈淮青】方向），原本面无表情，忽然嘴角微微上扬，露出一丝带着讽刺意味的笑，但笑意未达眼底，眼神中带着冷意和审视，展示脸部。"
    },
    {
      "shot": 3,
      "replacement": "【分镜3】\n近景，固定镜头，【姜蘅之】位于画面中央，处于画面层次的前景，微微偏头，身体朝向画面左侧，视线看向画面左侧的【沈淮青】，语气带着讥诮，缓缓说道：“沈淮青，你脑子没毛病吧？”展示上半身。"
    },
    {
      "shot": 4,
      "replacement": "【分镜4】\n近景，轻微环绕，【姜蘅之】位于画面中央，处于画面层次的前景，向前迈了半步，身体朝向画面左侧，视线看向画面左侧的【沈淮青】，目光如刀，语气加重：“你将她绑来有何用？”展示上半身。"
    },
    {
      "shot": 5,
      "replacement": "【分镜5】\n近景，手持晃动，【姜蘅之】位于画面中央，处于画面层次的前景，身体朝向画面左侧，视线看向画面左侧的【沈淮青】，情绪骤然爆发，语气凌厉：“你们沈家，从里到外，都烂透了！”她的手指微微攥紧，眼神中带着怒意和失望，展示上半身。"
    },
    {
      "shot": 6,
      "replacement": "【分镜6】\n近景，缓慢推近，【沈淮青】位于画面中央，处于画面层次的前景，身体朝向画面右侧，视线看向画面右侧的【姜蘅之】，脸色涨红，嘴唇微颤，眼神中闪过一丝难堪和愤怒，呼吸变得急促，像是被戳中了痛处，展示上半身。"
    },
    {
      "shot": 7,
      "replacement": "【分镜7】\n特写，固定镜头，【沈淮青】位于画面中央，处于画面层次的前景，面部朝向镜头，视线看向镜头前方（即画面右侧的【姜蘅之】方向），眼睛微微泛红，声音发紧，带着被冒犯的怒意：“你……你这是何意？”展示脸部。"
    },
    {
      "shot": 8,
      "replacement": "【分镜8】\n近景，跟随运镜，【沈淮青】位于画面中央，处于画面层次的前景，向前逼近一步，身体朝向画面右侧，视线看向画面右侧的【姜蘅之】，语气中带上一丝讽刺：“你是想让我也给你负荆请罪吗？”展示上半身。"
    },
    {
      "shot": 9,
      "replacement": "【分镜9】\n特写，缓慢推近，【沈淮青】位于画面中央，处于画面层次的前景，面部朝向镜头，视线看向镜头前方（即画面右侧的【姜蘅之】方向），语气骤然软下来，带着恳求和几乎要哭出来的颤抖：“可以啊，只要你救我娘，你让我做什么都可以……”他的眼神中满是卑微和绝望，展示脸部。"
    },
    {
      "shot": 10,
      "replacement": "【分镜10】\n近景，固定镜头，【姜蘅之】位于画面中央，处于画面层次的前景，身体朝向画面左侧，视线看向画面左侧的【沈淮青】，看着他的模样，眼神中闪过一丝怜悯，但随即被冷漠取代，她的表情平静而疏离，展示上半身。"
    },
    {
      "shot": 11,
      "replacement": "【分镜11】\n近景，固定镜头，【姜蘅之】位于画面中央，处于画面层次的前景，身体朝向画面左侧，视线看向画面左侧的【沈淮青】，平静地开口，语气像在陈述一个事实：“你来求我，我听见了。”展示上半身。"
    },
    {
      "shot": 12,
      "replacement": "【分镜12】\n近景，轻微推近，【姜蘅之】位于画面中央，处于画面层次的前景，身体朝向画面左侧，视线微微移开，看向画面右侧（或镜头侧方），语气更冷了几分：“我不救，你也听见了。”展示上半身。"
    },
    {
      "shot": 13,
      "replacement": "【分镜13】\n近景，固定镜头，【姜蘅之】位于画面中央，处于画面层次的前景，微微侧身，身体朝向画面右侧，视线看向画面左侧（或镜头前方），做了个“请”的手势，语气淡漠而决绝：“走吧。”她的眼神中没有丝毫动摇，仿佛这件事已经画上句号，展示上半身。"
    }
  ]
}

{
  "changes": [
    {
      "shot": 1,
      "replacement": "【分镜1】\n中景，夜晚的庭院，昏黄的灯光从侧方打来。画面左侧是【沈淮青】，他站着，神情焦躁，位于画面层次的中景，身体朝向画面右侧，视线看向画面右侧的姜蘅之；画面右侧是【姜蘅之】，他背手而立，神色平静，位于画面层次的中景，身体朝向画面左侧，视线看向画面左侧的沈淮青。两人之间隔着数步距离，地面投下长长的影子。画面静止片刻，气氛沉默。"
    },
    {
      "shot": 2,
      "replacement": "【分镜2】\n切至【姜蘅之】的脸部特写，他微微勾起嘴角，露出一丝带着冷意的笑，眼神凉薄地看着画面左侧的方向，缓缓开口：“沈淮青——”"
    },
    {
      "shot": 3,
      "replacement": "【分镜3】\n近景，【姜蘅之】站在画面中央偏右，位于画面层次的中景，他微微歪头，身体朝向画面左侧，视线看向画面左侧的沈淮青，语气带着嘲讽：“你脑子没毛病吧？”说完，他轻轻笑了一声，眼神里满是轻蔑。"
    },
    {
      "shot": 4,
      "replacement": "【分镜4】\n缓慢推近，【姜蘅之】的视线微微上移，仿佛在审视对方，身体朝向画面左侧，视线看向画面左侧的沈淮青，语气变得沉冷：“你将她绑来有何用？”他的目光锐利，带着质问。"
    },
    {
      "shot": 5,
      "replacement": "【分镜5】\n脸部特写，【姜蘅之】压低了声音，一字一句地说：“你们沈家，从里到外，都烂透了！”他的眼神里带着嫌恶和决绝，说完后，嘴唇紧抿。"
    },
    {
      "shot": 6,
      "replacement": "【分镜6】\n切至【沈淮青】的脸部特写，他脸色涨红，又羞又怒，眉头紧皱，开口时有些结巴：“你……你这是何意？”他呼吸急促，胸口起伏，显然被激怒了。"
    },
    {
      "shot": 7,
      "replacement": "【分镜7】\n近景，【沈淮青】站在画面中央偏左，位于画面层次的中景，他微微向前一步，身体朝向画面右侧，视线看向画面右侧的姜蘅之，语气从愤怒转为讽刺：“你是想让我也给你负荆请罪吗？”他咬着牙，眼神里带着不甘。"
    },
    {
      "shot": 8,
      "replacement": "【分镜8】\n【沈淮青】的脸部特写，他的语气突然软下来，带着一丝恳求和卑微：“可以啊，只要你救我娘……”他停顿了一下，声音低了下去，“你让我做什么都可以……”他的眼神里带着乞求。"
    },
    {
      "shot": 9,
      "replacement": "【分镜9】\n切回【姜蘅之】，他听完后沉默了一瞬，眼神平静地看着画面左侧的沈淮青，没有任何情绪波动，仿佛在等待对方说完。"
    },
    {
      "shot": 10,
      "replacement": "【分镜10】\n近景，【姜蘅之】缓缓开口，语气平静而清晰：“你来求我，我听见了。”他的声音没有起伏，但眼神里带着一种疏离。"
    },
    {
      "shot": 11,
      "replacement": "【分镜11】\n脸部特写，【姜蘅之】继续说，声音冷淡而坚定：“我不救，你也听见了。”他微微抬了抬下巴，仿佛在宣告对话的终结。"
    },
    {
      "shot": 12,
      "replacement": "【分镜12】\n全景，【姜蘅之】说完“走吧”后，微微侧身，转身向画面右侧走去，步态从容。画面左侧的【沈淮青】站在原地，怔怔地看着他的背影，没有追上去。昏黄的灯光下，两人的影子逐渐拉开距离。"
    }
  ]
}

